"""Coverage, calibration and exact-table accounting.

Calibration decides the matching validation rows of every generalized
interval pattern, derives the exact score of a cluster and keeps the
surviving patterns.  The exact table accounting reports the number of
distinct exact keys of a bank.
"""
from collections import defaultdict
from fractions import Fraction
from itertools import product

import numpy as np

from offline_discovery.rule_generate import PADDING, real_prefix

SMALL = Fraction(1, 10000)


def _intervals(bounds):
    return tuple((low, high) for low, high in bounds)


def calibrate(clusters, validation, classes, threshold):
    """Attach hits, score and the keep decision to every cluster."""
    totals = [0] * classes
    prefixes = []
    for row in validation:
        totals[row['class']] += 1
        prefixes.append((row['class'], np.array(real_prefix(row['values']), dtype=np.int64)))
    hits = {cluster['id']: [0] * classes for cluster in clusters}
    groups = defaultdict(list)
    for cluster in clusters:
        groups[len(cluster['bounds'])].append(cluster)
    for length, items in sorted(groups.items()):
        patterns = {}
        for cluster in items:
            patterns.setdefault(_intervals(cluster['bounds']), []).append(cluster)
        keys = list(patterns)
        if not keys:
            continue
        low = np.array([[bound[0] for bound in key] for key in keys], dtype=np.int64)
        high = np.array([[bound[1] for bound in key] for key in keys], dtype=np.int64)
        # A pattern whose interval never holds a value seen in the validation
        # data cannot match any row and is dropped from the scan.
        present = np.zeros(3029, dtype=bool)
        for _, prefix in prefixes:
            if prefix.size:
                present[prefix] = True
        usable = []
        for index in range(len(keys)):
            ok = True
            for position in range(length):
                if not present[low[index][position]:high[index][position] + 1].any():
                    ok = False
                    break
            if ok:
                usable.append(index)
        if not usable:
            continue
        low = low[usable]
        high = high[usable]
        usable_keys = [keys[index] for index in usable]
        for row_class, prefix in prefixes:
            size = prefix.size
            if size < length:
                continue
            window = size - length + 1
            accumulator = None
            for position in range(length):
                segment = prefix[position:position + window]
                lower = low[:, position][:, None]
                upper = high[:, position][:, None]
                allowed = (lower <= segment[None, :]) & (upper >= segment[None, :])
                accumulator = allowed if accumulator is None else (accumulator & allowed)
            for index in np.flatnonzero(accumulator.any(axis=1)):
                for cluster in patterns[usable_keys[int(index)]]:
                    hits[cluster['id']][row_class] += 1
    for cluster in clusters:
        target = cluster['class']
        counts = hits[cluster['id']]
        inner = Fraction(counts[target], totals[target]) if totals[target] else Fraction(0)
        outer = Fraction(0)
        for label in range(classes):
            if label == target or not totals[label]:
                continue
            value = Fraction(counts[label], totals[label])
            if value > outer:
                outer = value
        score = inner / (outer + SMALL)
        cluster['hits'] = counts
        cluster['score'] = score
        cluster['kept'] = score > threshold
    return clusters


def exact_key_count(bounds, limit):
    """Number of exact keys of one pattern, saturating at ``limit`` + 1."""
    choices = []
    for low, high in bounds:
        values = [value for value in range(low, high + 1) if value != PADDING]
        if not values:
            return 0
        choices.append(values)
    return len(list(product(*choices)))


def exact_entry_count(clusters, capacity):
    """Distinct exact keys of a bank, clipped to ``capacity`` + 1.

    Identical keys of the same length occupy one entry; keys of different
    lengths are distinct.
    """
    limit = capacity + 1
    groups = defaultdict(list)
    for cluster in clusters:
        groups[len(cluster['bounds'])].append(cluster['bounds'])
    total = 0
    for length, boxes in sorted(groups.items()):
        distinct = set(tuple(_intervals(box)) for box in boxes)
        total += _union_size(distinct, limit)
        if total > capacity:
            return limit
    return min(total, limit)


def _union_size(boxes, limit):
    """Distinct keys of a set of patterns, saturating at ``limit`` + 1."""
    keys = set()
    for box in boxes:
        choices = []
        for low, high in box:
            values = [value for value in range(low, high + 1) if value != PADDING]
            if not values:
                choices = None
                break
            choices.append(values)
        if not choices:
            continue
        for key in product(*choices):
            keys.add(key)
            if len(keys) > limit:
                return limit + 1
    return len(keys)
"""Online pattern matching structures of one release bank.

A range bank keeps one generalized interval per kept cluster, an exact bank
keeps one table per pattern length.  Both are matched against the contiguous
suffix of the epoch that ends at the arriving packet.
"""
from collections import defaultdict

PADDING = 1514
VALUE_MAX = 3028


def build_tables(patterns):
    """Per coordinate tables mapping a value to the clusters that accept it.

    ``patterns`` is the list of interval vectors of one pattern length; the
    tables are indexed by the cluster position inside that list.
    """
    length = len(patterns[0])
    tables = []
    for position in range(length):
        events = []
        for index, bounds in enumerate(patterns):
            bit = 1 << index
            events.append((bounds[position][0], bit))
            events.append((bounds[position][1] + 1, bit))
        events.sort()
        table = [0] * (VALUE_MAX + 1)
        mask = 0
        cursor = 0
        for value in range(VALUE_MAX + 1):
            while cursor < len(events) and events[cursor][0] == value:
                mask ^= events[cursor][1]
                cursor += 1
            table[value] = mask
        tables.append(table)
    return tables


class PatternBank:
    """Kept clusters of one release, ordered by deployment priority."""

    def __init__(self, clusters):
        # clusters: kept clusters in priority order
        self.clusters = clusters
        self.groups = {}
        grouped = defaultdict(list)
        for rank, cluster in enumerate(clusters):
            grouped[len(cluster['bounds'])].append((rank, cluster))
        for length, items in grouped.items():
            patterns = [cluster['bounds'] for _, cluster in items]
            self.groups[length] = {
                'clusters': [cluster for _, cluster in items],
                'ranks': [rank for rank, _ in items],
                'tables': build_tables(patterns),
            }

    def match(self, features):
        """Highest priority cluster matching the suffix that ends here."""
        count = len(features)
        best_rank = None
        best = None
        for length, group in self.groups.items():
            if length > count:
                continue
            base = count - length
            mask = None
            tables = group['tables']
            for position in range(length):
                allowed = tables[position][features[base + position]]
                if not allowed:
                    mask = None
                    break
                mask = allowed if mask is None else (mask & allowed)
            if mask:
                index = (mask & -mask).bit_length() - 1
                rank = group['ranks'][index]
                if best_rank is None or rank < best_rank:
                    best_rank = rank
                    best = group['clusters'][index]
        return best
